package br.com.equilibra.recurrence.application; import br.com.equilibra.account.infrastructure.AssetAccountRepository;import br.com.equilibra.category.domain.CategoryApplicability;import br.com.equilibra.category.infrastructure.CategoryRepository;import br.com.equilibra.recurrence.api.RecurrenceDtos;import br.com.equilibra.recurrence.domain.*;import br.com.equilibra.recurrence.infrastructure.RecurrenceRuleRepository;import br.com.equilibra.shared.api.CurrentUser;import br.com.equilibra.shared.web.exception.ResourceNotFoundException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class RecurrenceRuleService{private final RecurrenceRuleRepository repository;private final AssetAccountRepository accounts;private final CategoryRepository categories;private final CurrentUser currentUser;public RecurrenceRuleService(RecurrenceRuleRepository r,AssetAccountRepository a,CategoryRepository c,CurrentUser u){repository=r;accounts=a;categories=c;currentUser=u;}private String owner(){return currentUser.id().toString();}@Transactional public RecurrenceDtos.Response create(RecurrenceDtos.Create r){String o=owner();validateRefs(r.type(),r.categoryId(),r.accountId(),o);return response(repository.save(new RecurrenceRule(o,r.type(),r.description(),r.amount(),r.categoryId(),r.accountId(),r.frequency(),r.startDate(),r.endDate(),r.dueDay())));}@Transactional(readOnly=true)public List<RecurrenceDtos.Response> list(){return repository.findAllByOwnerIdOrderByCreatedAtDesc(owner()).stream().map(this::response).toList();}@Transactional(readOnly=true)public RecurrenceDtos.Response get(String id){return response(find(id));}@Transactional public RecurrenceDtos.Response update(String id,RecurrenceDtos.Update r){RecurrenceRule x=find(id);x.rename(r.description());x.changeAmount(r.amount());return response(repository.save(x));}@Transactional public RecurrenceDtos.Response pause(String id){RecurrenceRule x=find(id);x.pause();return response(repository.save(x));}@Transactional public RecurrenceDtos.Response resume(String id){RecurrenceRule x=find(id);x.resume();return response(repository.save(x));}@Transactional public RecurrenceDtos.Response end(String id){RecurrenceRule x=find(id);x.end();return response(repository.save(x));}@Transactional public RecurrenceDtos.Response cancel(String id){RecurrenceRule x=find(id);x.cancel();return response(repository.save(x));}private RecurrenceRule find(String id){return repository.findByIdAndOwnerId(id,owner()).orElseThrow(()->new ResourceNotFoundException("Recurrence not found."));}private void validateRefs(RecurrenceType type,String cat,String acc,String o){if(accounts.findByIdAndOwnerId(acc,o).filter(a->a.isActive()).isEmpty())throw new ResourceNotFoundException("Account not found.");var c=categories.findByIdAndOwnerId(cat,o).filter(x->x.isActive()).orElseThrow(()->new ResourceNotFoundException("Category not found."));if(type==RecurrenceType.EXPENSE&&c.getApplicability()==CategoryApplicability.INCOME||type==RecurrenceType.INCOME&&c.getApplicability()==CategoryApplicability.EXPENSE)throw new IllegalArgumentException("Category is incompatible with recurrence type.");}private RecurrenceDtos.Response response(RecurrenceRule x){return new RecurrenceDtos.Response(x.getId(),x.getType(),x.getDescription(),x.getAmount(),x.getCategoryId(),x.getAccountId(),x.getFrequency(),x.getStartDate(),x.getEndDate(),x.getDueDay(),x.getStatus(),x.getCreatedAt(),x.getUpdatedAt());}}
